export const landingHTML="<section id=\"welcome\" aria-labelledby=\"welcome-question\"><div class=\"welcome-brand\"><img src=\"assets/debtfreelately-mark-clean.png\" alt=\"\"><div>DebtFreeLately</div></div><div class=\"welcome-content\"><p class=\"welcome-kicker\">NO ONE GETS DEBT-FREE ALONE.</p><h1 id=\"welcome-question\">Are you <em>Broke</em> or <em>Bros?</em></h1><div class=\"role-options\"><button class=\"role-card\" data-role=\"Broke\"><span class=\"role-symbol\" aria-hidden=\"true\">↗</span><strong>Broke</strong><span class=\"role-caption\">I need a hand</span><span class=\"role-arrow\" aria-hidden=\"true\">↗</span></button><button class=\"role-card role-bro\" data-role=\"Bros\"><span class=\"role-symbol\" aria-hidden=\"true\">♡</span><strong>Bros</strong><span class=\"role-caption\">I'm here to help</span><span class=\"role-arrow\" aria-hidden=\"true\">↗</span></button></div><p class=\"welcome-hint\">A little kindness. A fresh start.</p></div><div class=\"welcome-footer\">Together, we move forward. <a href=\"#how-it-works\">How It Works</a><a href=\"/privacy.html\">Privacy</a><a href=\"/transparency.html\">Transparency</a><a href=\"/community-safety.html\">Community Safety</a><a href=\"/about.html\">About Us</a><span>DebtFreeLately © 2026</span></div></section>";

export const infoHTML="<main class=\"about-main\"><article class=\"about-shell\"><div class=\"about-intro\"><p class=\"about-eyebrow\">GET TO KNOW US</p><span class=\"about-name\">About DebtFreeLately</span><h1>No One Gets Debt Free Alone.</h1><p class=\"about-subtitle\">Because everyone deserves a second chance.</p></div>\n<figure class=\"about-hero\"><img src=\"assets/about-community.png\" width=\"1536\" height=\"1024\" alt=\"Two people sharing an encouraging conversation and holding hands across a table in a bright, plant-filled café.\"><figcaption>Illustrative image</figcaption></figure>\n<section class=\"about-opening\" aria-labelledby=\"about-opening-title\"><h2 id=\"about-opening-title\">A Little Help Can Change Everything.</h2><p>Life doesn't always go as planned.</p><p>Sometimes, unexpected circumstances, financial setbacks, or simply being in the wrong place at the wrong time can leave someone facing debt they never imagined.</p><p>We believe that experiencing financial hardship doesn't define who you are, and asking for help should never be a source of shame.</p><p><strong>That's why DebtFreeLately was created.</strong></p></section>\n<section class=\"about-story about-section\" aria-labelledby=\"about-story-title\"><p class=\"about-eyebrow\">A COMMUNITY WITH PURPOSE</p><h2 id=\"about-story-title\">Our Story</h2><p>DebtFreeLately was founded on a simple belief: no one should have to face financial hardship alone.</p><p>We're building a community that connects people struggling with debt, whom we call <strong>Broke</strong>, with compassionate individuals willing to lend a helping hand, known as <strong>Bros</strong>.</p><p>Our platform is designed to turn kindness into meaningful financial support, helping people move toward a fresh start.</p></section>\n<section class=\"about-section\" aria-labelledby=\"about-difference-title\"><h2 id=\"about-difference-title\">How We're Different</h2><p>We believe generosity deserves trust.</p><p>That's why DebtFreeLately is being designed around identity verification, debt documentation, independent creditor confirmation, and a direct-to-creditor payment model.</p><p>Rather than handing financial contributions directly to individuals requesting support, our goal is to ensure payments are directed toward confirmed financial obligations through authorised payment channels.</p><p>We want supporters to understand where their contributions go and give those seeking help the dignity and privacy they deserve.</p><a class=\"about-text-link\" href=\"/transparency.html\">Our approach and current progress →</a></section>\n<div class=\"about-purpose-grid\"><section aria-labelledby=\"about-mission-title\"><span class=\"about-purpose-mark\" aria-hidden=\"true\">↗</span><h2 id=\"about-mission-title\">Our Mission</h2><p><strong>To make financial kindness more accessible, transparent, and meaningful.</strong></p><p>We aim to create a place where asking for help feels safe, offering help feels worthwhile, and every contribution brings someone closer to financial freedom.</p></section><section aria-labelledby=\"about-vision-title\"><span class=\"about-purpose-mark\" aria-hidden=\"true\">☼</span><h2 id=\"about-vision-title\">Our Vision</h2><p>A world where financial hardship doesn't mean losing hope.</p><p>Where generosity connects strangers.<br>Where people are given opportunities to rebuild.<br>And where no one has to face debt alone.</p></section></div>\n<section class=\"about-section\" aria-labelledby=\"about-beliefs-title\"><p class=\"about-eyebrow\">THE VALUES THAT GUIDE US</p><h2 id=\"about-beliefs-title\">What We Believe</h2><div class=\"about-values\"><div><span aria-hidden=\"true\">♡</span><h3>Compassion Without Judgment</h3><p>Everyone has a story. We believe people deserve understanding, not shame.</p></div><div><span aria-hidden=\"true\">◇</span><h3>Trust Through Transparency</h3><p>Every contribution deserves clarity and accountability.</p></div><div><span aria-hidden=\"true\">♧</span><h3>Privacy With Dignity</h3><p>Your personal circumstances are yours to share, on your own terms.</p></div><div><span aria-hidden=\"true\">✧</span><h3>Community With Purpose</h3><p>Small acts of kindness can create meaningful changes in someone's life.</p></div></div></section>\n<section class=\"about-closing\" aria-labelledby=\"about-closing-title\"><h2 id=\"about-closing-title\">A Fresh Start Begins With Us.</h2><p>Whether you're here because you need a helping hand or because you want to make a difference, you belong in a community built on empathy, trust, and hope.</p><strong>DebtFreeLately — No One Gets Debt Free Alone.</strong></section>\n</article></main>";

// Preview follows effective placement overrides without reading application state.
export function previewCampaign({placements=[],campaigns=[],zoneId,device='desktop'}){
 const relevant=placements.filter(p=>!p.device||p.device===device);
 const placement=relevant.find(p=>p.id===zoneId);
 if(placement?.enabled===false)return null;
 const ids=Array.isArray(placement?.campaignIds)?placement.campaignIds:[];
 const suitable=c=>{const fields=c.draft||c.live||c;return !Array.isArray(fields.devices)||fields.devices.includes(device);};
 if(ids.length)return campaigns.find(c=>ids.includes(c.id)&&suitable(c))||null;
 return campaigns.find(c=>{const fields=c.draft||c.live||c;return suitable(c)&&fields.placement===zoneId&&!relevant.some(p=>p.id!==zoneId&&p.enabled!==false&&p.campaignIds?.includes(c.id));})||null;
}
